  $visitWeekly=$pdo->query("SELECT YEARWEEK(visited_at,3) bucket,MIN(DATE(visited_at)) start_date,COUNT(*) views,COUNT(DISTINCT visitor_id) uniques FROM public_site_visits WHERE visited_at>=DATE_SUB(CURDATE(),INTERVAL 55 DAY) GROUP BY YEARWEEK(visited_at,3) ORDER BY bucket")->fetchAll()?:[];
  $visitMonthly=$pdo->query("SELECT DATE_FORMAT(visited_at,'%Y-%m') bucket,COUNT(*) views,COUNT(DISTINCT visitor_id) uniques FROM public_site_visits WHERE visited_at>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY DATE_FORMAT(visited_at,'%Y-%m') ORDER BY bucket")->fetchAll()?:[];
